describe('proof', () => {
  it('fails on the patched build', () => {
    // YAML 1.1 schema resolves signed non-decimal integers.
    // Unpatched: parseYamlInteger strips the leading '+', so
    //   '+0x1f' -> parseInt('1f', 16) === 31
    //   '+0b101' -> parseInt('101', 2) === 5
    //   '+010'  -> parseInt('010', 8) === 8
    // The patch skips stripping '+', so these fall through to
    // parseInt(value, 10): '+0x1f' and '+0b101' become 0, '+010' becomes 10.
    assert.strictEqual(load('+0x1f', { schema: YAML11_SCHEMA }), 31);
    assert.strictEqual(load('+0b101', { schema: YAML11_SCHEMA }), 5);
    assert.strictEqual(load('+010', { schema: YAML11_SCHEMA }), 8);
  });
});

