import { describe, it } from 'node:test';
import assert from 'node:assert';
import { dump, load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // A Map instance is not a plain object, so the default map tag must not
    // identify it: dumping one must throw instead of silently dropping data.
    assert.throws(
      () => dump(new Map([['a', 1]])),
      /unacceptable kind of an object to dump/
    );

    // Conversely, a null-prototype object IS a plain object and must dump
    // (and round-trip) as an ordinary mapping.
    const nullProto = Object.create(null);
    nullProto.a = 1;
    assert.equal(dump(nullProto), 'a: 1\n');
    assert.deepEqual(load(dump(nullProto)), { a: 1 });
  });
});
